mapper.sql:
WHERE pv_requests.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId}) AND pv_requests.status >= 0

    AND (
    pv_requests.code LIKE CONCAT('%', #{filter.searchText}, '%')
    OR v.name LIKE CONCAT('%', #{filter.searchText}, '%')
    OR (
    SELECT pr_code
    FROM purchase_requests
    WHERE status > 0
    AND id IN (
    SELECT order_id
    FROM pv_request_orders
    WHERE status = 2
    AND pv_request_id = pv_requests.id
    )
    ) LIKE CONCAT('%', #{filter.searchText}, '%')
    OR (
    SELECT po_code
    FROM purchase_orders
    WHERE status > 0
    AND pv_request_id = pv_requests.id
    ) LIKE CONCAT('%', #{filter.searchText}, '%')
    )


    AND pv_requests.order_date >= #{filter.dateFrom}


    AND pv_requests.order_date <= #{filter.dateTo}


     AND pv_requests.status = #{filter.status}


    AND pv_requests.created_by = #{userId}

mapper.select:
SELECT



ORDER BY


        ${filter.orderBy}


        pv_requests.id DESC



    LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT
  (SELECT symbol FROM currency_centers WHERE id = pv_requests.currency_center_id) AS currencySymbol,


WHERE pv_requests.id = #{id}

( SELECT 1 AS `type`, pv_request_details.id AS id, pv_request_details.product_id AS itemId, products.code AS itemCode, products.name AS itemName, IFNULL(products.small_val_uom,1) / IFNULL(pv_request_details.conversion, 1) AS conversion, pv_request_details.qty AS qty, pv_request_details.qty_uom_id AS uomId, uoms.name AS uomName, pv_request_details.unit_cost AS unitCost, pv_request_details.total_cost AS totalCost, IFNULL(pv_request_details.note, '') AS note FROM pv_request_details LEFT JOIN products ON products.id = pv_request_details.product_id LEFT JOIN uoms ON uoms.id = pv_request_details.qty_uom_id WHERE pv_request_details.pv_request_id = #{id}
)
UNION
(
SELECT 2 AS `type`, pv_request_services.id AS id, pv_request_services.service_id AS itemId, services.sku AS itemCode, services.name AS itemName, 1 AS conversion, pv_request_services.qty AS qty, NULL AS uomId, NULL AS uomName, pv_request_services.unit_cost AS unitCost, pv_request_services.total_cost AS totalCost, IFNULL(pv_request_services.note, '') AS note FROM pv_request_services LEFT JOIN services ON services.id = pv_request_services.service_id WHERE pv_request_services.pv_request_id = #{id}
)
UNION
(
SELECT 3 AS `type`, pv_request_miscs.id AS id, pv_request_miscs.id AS itemId, NULL AS itemCode, pv_request_miscs.description AS itemName, 1 AS conversion, pv_request_miscs.qty AS qty, pv_request_miscs.qty_uom_id AS uomId, uoms.name AS uomName, pv_request_miscs.unit_cost AS unitCost, pv_request_miscs.total_cost AS totalCost, IFNULL(pv_request_miscs.note, '') AS note FROM pv_request_miscs LEFT JOIN uoms ON uoms.id = pv_request_miscs.qty_uom_id WHERE pv_request_miscs.pv_request_id = #{id}
) ORDER BY `type` DESC, id ASC

